import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  DirectionalLight,
  SRGBColorSpace
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();

  // Create local cleanup tracking
  const timelines = [];
  const materialsToDispose = [];
  const geometriesToDispose = [];

  // Colors
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- STAGE / BACKDROP ---
  // Create a subtle backdrop plane to satisfy the "Stage, never void" requirement
  const stageGeo = new PlaneGeometry(7.0, 6.0);
  geometriesToDispose.push(stageGeo);

  // We use standard material for backdrop so it reacts slightly to lights
  const stageMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.9,
    metalness: 0.1,
    depthWrite: false
  });
  materialsToDispose.push(stageMat);

  const stageMesh = new Mesh(stageGeo, stageMat);
  stageMesh.position.set(0, 0, -2.5);
  group.add(stageMesh);

  // --- LOCAL ACCENT Rim Light ---
  const localRimLight = new DirectionalLight(colors.accent, 1.2);
  localRimLight.position.set(-2, 3, 2);
  group.add(localRimLight);

  // --- MAIN JOURNAL CARD CARD ---
  // 16:10 aspect ratio based on atlas region (512x320)
  const cardGeo = new PlaneGeometry(3.2, 2.0);
  geometriesToDispose.push(cardGeo);

  // Interactive Card uses MeshStandardNodeMaterial for reactive highlights
  const cardMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.35,
    transparent: true,
    opacity: 0.98
  });
  materialsToDispose.push(cardMat);

  const cardMesh = new Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Load the product image directly onto a sibling/child layered plane slightly in front
  const imageOffset = 0.01;
  const imageGeo = new PlaneGeometry(3.1, 1.9);
  geometriesToDispose.push(imageGeo);

  const imageMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1.0,
    depthWrite: false
  });
  materialsToDispose.push(imageMat);

  const imageMesh = new Mesh(imageGeo, imageMat);
  imageMesh.position.set(0, 0, imageOffset);
  group.add(imageMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = SRGBColorSpace;
      imageMat.colorNode = texture;
      imageMat.needsUpdate = true;
    });
  }

  // Stock Badge overlay (Dynamic via data binding simulation)
  // Let's create an active-state badge dot + label
  const badgeGroup = new Group();
  badgeGroup.position.set(-1.1, 0.7, imageOffset * 2);

  const badgeDotGeo = new PlaneGeometry(0.12, 0.12);
  geometriesToDispose.push(badgeDotGeo);
  const badgeDotMat = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  materialsToDispose.push(badgeDotMat);
  const badgeDot = new Mesh(badgeDotGeo, badgeDotMat);
  badgeGroup.add(badgeDot);

  // Create Text via MSDF Text utility
  const badgeText = ctx.fontAtlas.createText('IN STOCK', {
    fontSize: 0.08,
    color: colors.paper,
    align: 'left'
  });
  badgeText.position.set(0.12, -0.03, 0);
  badgeGroup.add(badgeText);
  group.add(badgeGroup);

  // Add card descriptor text layer to satisfy visual richness
  const labelText = ctx.fontAtlas.createText('ATELIER JOURNAL 03', {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center'
  });
  labelText.position.set(0, -0.7, imageOffset * 2);
  group.add(labelText);

  // Set initial spatial properties from spec
  group.position.set(3.2, -0.3, 0);

  // --- INTERACTION HANDLING ---
  let isHovered = false;

  const onOver = () => {
    if (isHovered) return;
    isHovered = true;

    // Hover Lift (subtle, 0.15 units)
    gsap.killTweensOf(cardMesh.position);
    gsap.killTweensOf(imageMesh.position);
    gsap.killTweensOf(badgeGroup.position);
    gsap.killTweensOf(labelText.position);

    gsap.to([cardMesh.position, imageMesh.position, badgeGroup.position, labelText.position], {
      z: '+=0.15',
      duration: 0.3,
      ease: 'power3.out'
    });

    gsap.to(cardMat, {
      roughness: 0.4,
      duration: 0.3
    });
  };

  const onOut = () => {
    if (!isHovered) return;
    isHovered = false;

    gsap.killTweensOf(cardMesh.position);
    gsap.killTweensOf(imageMesh.position);
    gsap.killTweensOf(badgeGroup.position);
    gsap.killTweensOf(labelText.position);

    // Reset base positions
    gsap.to(cardMesh.position, { z: 0, duration: 0.3, ease: 'power2.out' });
    gsap.to(imageMesh.position, { z: imageOffset, duration: 0.3, ease: 'power2.out' });
    gsap.to(badgeGroup.position, { z: imageOffset * 2, duration: 0.3, ease: 'power2.out' });
    gsap.to(labelText.position, { z: imageOffset * 2, duration: 0.3, ease: 'power2.out' });

    gsap.to(cardMat, {
      roughness: 0.6,
      duration: 0.3
    });
  };

  const onClick = () => {
    // Press down effect
    const bounceTl = gsap.timeline();
    timelines.push(bounceTl);
    bounceTl.to(group.scale, {
      x: 0.95,
      y: 0.95,
      z: 0.95,
      duration: 0.1,
      ease: 'back.out(2)'
    }).to(group.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.3,
      ease: 'power4.out'
    });

    // Notify the framework
    ctx.emit('hub-journal.select', { id: 'journal-card-3' });
  };

  // Attach handlers the scene runner expects
  group.userData.handlers = {
    pointerover: onOver,
    pointerout: onOut,
    click: onClick
  };

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    materialsToDispose.forEach(m => m.dispose());
    geometriesToDispose.forEach(g => g.dispose());
  };

  return group;
}
